package com.schooloss.fullnative.feature.auth;
import android.content.*;import android.os.Bundle;import android.text.InputType;import android.view.*;import android.widget.*;import com.schooloss.fullnative.core.*;import com.schooloss.fullnative.feature.home.HomeActivity;import org.json.JSONObject;
public final class LoginActivity extends BaseActivity {
 @Override protected void onCreate(Bundle b){super.onCreate(b);loading("Opening SchoolOS","Checking your secure session…");io.execute(()->{try{JSONObject r=api.get("session");runOnUiThread(()->accept(r));}catch(Exception e){runOnUiThread(()->form(null));}});}
 private void accept(JSONObject r){if(r.optBoolean("school_required",false)){form("Select a school workspace first.");return;}api.store().session(r);startActivity(new Intent(this,HomeActivity.class));finish();}
 private void form(String initial){LinearLayout p=Ui.v(this);p.setPadding(Ui.dp(this,18),Ui.dp(this,18),Ui.dp(this,18),Ui.dp(this,24));p.setBackgroundColor(Constants.BG);p.addView(Ui.text(this,"SchoolOS",25,Constants.TEXT,true));p.addView(Ui.text(this,"FULL NATIVE ANDROID",9,Constants.BLUE,true));p.addView(Ui.gap(this,16));com.google.android.material.card.MaterialCardView card=Ui.card(this);LinearLayout in=Ui.v(this);in.setPadding(Ui.dp(this,18),Ui.dp(this,18),Ui.dp(this,18),Ui.dp(this,18));in.addView(Ui.text(this,"Sign in",28,Constants.TEXT,true));in.addView(Ui.text(this,"Use your existing SchoolOS account. Your role, school and permissions remain server-authoritative.",12,Constants.MUTED,false));TextView err=Ui.text(this,initial==null?"":initial,11,0xFFB43646,true);err.setVisibility(initial==null?View.GONE:View.VISIBLE);in.addView(Ui.gap(this,12));in.addView(err);EditText email=new EditText(this);email.setHint("Email address");email.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);in.addView(email);EditText pass=new EditText(this);pass.setHint("Password");pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);in.addView(pass);com.google.android.material.button.MaterialButton go=Ui.button(this,"Sign In",Constants.BLUE,0xFFFFFFFF);go.setOnClickListener(v->{String e=email.getText().toString().trim(),pw=pass.getText().toString();if(e.isEmpty()||pw.isEmpty()){err.setText("Enter email and password.");err.setVisibility(View.VISIBLE);return;}go.setEnabled(false);go.setText("Signing in…");io.execute(()->{try{JSONObject body=new JSONObject();body.put("email",e);body.put("password",pw);JSONObject r=api.post("login",body);runOnUiThread(()->accept(r));}catch(Exception x){runOnUiThread(()->{go.setEnabled(true);go.setText("Sign In");err.setText(message(x));err.setVisibility(View.VISIBLE);});}});});in.addView(Ui.gap(this,10));in.addView(go);card.addView(in);p.addView(card);ScrollView s=new ScrollView(this);s.addView(p);setContentView(s);}
}